308: /**
309:   Checks socket's state for errors. If an error is encountered, the appropriate
310:   exception is thrown.
311: */
312: static void check_socket_error(Socket socket)
313: {
314:   int error = 0;
315:   socklen_t error_length = sizeof(error);
316: 
317:   if (::getsockopt(socket, SOL_SOCKET, SO_ERROR, (char *)&error, &error_length) != 0)
318:     throw_socket_error();
319: 
320:   if (error)
321: #ifdef _WIN32
322:     throw_error(error, winsock_error_category());
323: #else
324: 
325:     // Note: this is not very clear in POSIX docs, but the error code returned by
326:     // getsockopt(.. SO_ERROR ..) should be interpreted like errno value.
327:     // For example IBM docs for SO_ERROR specify:
328:     // "Return any pending errors in the socket. The value returned corresponds
