578: {
579:   addrinfo* result = NULL;
580:   addrinfo hints = {};
581:   in6_addr addr = {};
582: 
583:   hints.ai_flags = AI_NUMERICSERV;
584:   hints.ai_family = AF_INET;
585:   hints.ai_socktype = SOCK_STREAM;
586: 
587:   if (inet_pton(AF_INET, host_name, &addr) == 1)
588:   {
589:     hints.ai_family = AF_INET;
590:     hints.ai_flags |= AI_NUMERICHOST;
591:   }
592:   else
593:   {
594:     if (inet_pton(AF_INET6, host_name, &addr) == 1)
595:     {
596:       hints.ai_family = AF_INET6;
597:       hints.ai_flags |= AI_NUMERICHOST;
598:     }
599:   }
600: 
601:   // cast to unsigned because, unsigned short would use
602:   // std::to_string(int)
603:   int rc = getaddrinfo(host_name,
604:                        std::to_string(static_cast<unsigned>(port)).c_str(),
605:                        &hints, &result);
606: 
607: #ifdef EAI_SYSTEM
608:   if (EAI_SYSTEM == rc && errno)
609:     throw_posix_error();
610: #endif
611: 
612:   if (rc != 0)
613:     throw_error(rc, resolve_error_category());
614: 
615:   if (!result)
616:     throw_error(std::string("Invalid host name: ") + host_name);
617: 
618:   return result;
619: }
