828: 
829:     int select_result = poll_one(acceptor, POLL_MODE_CONNECT, true);
830: 
831:     if (select_result > 0)
832:     {
833:       sockaddr_in cli_addr = {};
834:       socklen_t cli_addr_length = sizeof(cli_addr);
835: 
836:       client = ::accept(acceptor, (sockaddr *)&cli_addr, &cli_addr_length);
837: 
838:       if (client == NULL_SOCKET)
839:         throw_socket_error();
840:     }
841:     else if (select_result == 0)
842:     {
843:       check_socket_error(acceptor);
844:     }
845:     else
846:     {
847:       throw_socket_error();
848:     }
