962: size_t recv_some(Socket socket, byte *buffer, size_t buffer_size, bool wait)
963: {
964:   if (buffer_size == 0)
965:     return 0;
966: 
967:   /*
968:     TODO: buffer size checks - throw error if passed buffer is bigger than
969:     some reasonable limit.
970:   */
971:   assert(buffer_size > 0);
972:   assert(buffer_size < (size_t)std::numeric_limits<int>::max());
973: 
974:   size_t bytes_received = 0;
975: 
976:   int select_result = poll_one(socket, POLL_MODE_READ, wait);
977: 
978:   if (select_result > 0)
979:   {
980:     int recv_result = ::recv(socket, reinterpret_cast<char *>(buffer),
981:                              static_cast<int>(buffer_size), 0);
982: 
983:     if (recv_result == 0)
984:     {
985:       throw connection::Error_eos();
