987:     else if (recv_result == SOCKET_ERROR)
988:     {
989: #ifdef _WIN32
990:       if (WSAGetLastError() == WSAEWOULDBLOCK)
991: #else
992:       if (errno == EAGAIN || errno == EWOULDBLOCK)
993: #endif
994:       {
995:         bytes_received = 0;
996:       }
997:       else
998:       {
999:         throw_socket_error();
1000:       }
1001:     }
1002:     else
1003:     {
1004:       assert(recv_result > 0);
1005:       bytes_received = static_cast<size_t>(recv_result);
1006:     }
1007:   }
1008:   else if (select_result == 0)
1009:   {
1010:     return 0;
1011:   }
1012:   else
1013:   {
1014:     throw_socket_error();
1015:   }
